// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 hash1, bytes32 hash2) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // First lock-in: admissible, always succeeds on both versions.
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash1);

        // General rule: a second lock-in from the same address must revert.
        vm.deal(actor, 2 ether);
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(hash2) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
